import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Space Analyzer","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/space-analyzer.md","filePath":"user-guide/space-analyzer.md","lastUpdated":1786498380000}'),r={name:"user-guide/space-analyzer.md"};function s(o,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="space-analyzer" tabindex="-1">Space Analyzer <a class="header-anchor" href="#space-analyzer" aria-label="Permalink to &quot;Space Analyzer&quot;">​</a></h1><p>The Space Analyzer turns Lertaro&#39;s existing file indexes into a fast, SpaceSniffer-style overview. It does not scan your disks, so it can open quickly even when several drives contain millions of entries.</p><h2 id="open-the-analyzer" tabindex="-1">Open the analyzer <a class="header-anchor" href="#open-the-analyzer" aria-label="Permalink to &quot;Open the analyzer&quot;">​</a></h2><p>Right-click the Lertaro tray icon and choose <strong>Space Analyzer</strong>. The first level shows every index currently loaded by Lertaro. Double-click a drive or folder with the left mouse button to enter it; use the up arrow or any breadcrumb to go back.</p><h2 id="read-and-use-the-view" tabindex="-1">Read and use the view <a class="header-anchor" href="#read-and-use-the-view" aria-label="Permalink to &quot;Read and use the view&quot;">​</a></h2><ul><li>The treemap on the left gives larger items more area. Light and dark shades indicate relative size, while different borders distinguish folders from files.</li><li>The list on the right shows the same items in descending size order. A thin bar under each row shows its share of the current location&#39;s visible total. Selecting an item in either view highlights it in both.</li><li>Right-click a card or list row to open the same actions menu used by search results, including opening, locating, copying, and any applicable plugin actions.</li><li>Tooltips appear only when the name or size has been truncated.</li></ul><h2 id="what-is-counted" tabindex="-1">What is counted <a class="header-anchor" href="#what-is-counted" aria-label="Permalink to &quot;What is counted&quot;">​</a></h2><p>Only entries already present in Lertaro&#39;s enabled indexes are included, and the analyzer never fills gaps by walking the filesystem. Excluded and unindexed content is absent. Hidden entries are shown, while system entries are not shown individually, although their size can still contribute to a visible ancestor folder&#39;s total.</p><p>Sizes are logical file sizes rather than allocated disk usage. Directory totals include their indexed descendants, and hard-linked file data is counted only once, so totals can differ from Windows Explorer or a sector-level disk analyzer.</p><p>The window automatically follows relevant in-memory index change events and coalesces bursts before updating the current view. The analyzer does not separately open or reload index cache files. Closing the window releases its rendered items and shared UI caches.</p>',10)])])}const y=a(r,[["render",s]]);export{p as __pageData,y as default};
